recipes.code:
{
  "inputs": [
    {
      "id": "obris-api-key",
      "type": "promptString",
      "description": "Your Obris API key from app.obris.ai/api-keys",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "obris-mcp@0.4.0"
      ],
      "env": {
        "OBRIS_API_KEY": "${input:obris-api-key}"
      }
    }
  }
}
